&reftitle.description;

 arrayfalsegetopt
 stringshort_options
 arraylong_options[]
 intrest_index&null;



 Analizza le opzioni passate allo script.

&reftitle.returnvalues;
Questa funzione restituisce un array di coppie opzione / argomento, &return.falseforfailure;.
L'analisi delle opzioni termina alla prima non-opzione trovata, tutto ciò che segue viene scartato.

  &reftitle.examples;



    Esempio di getopt: Le basi


<?php
// Script example.php
$options = getopt("f:hp:");
var_dump($options);
?>




shell> php example.php -fvalore -h


    &example.outputs;


array(2) {
  ["f"]=>
  string(6) "valore"
  ["h"]=>
  bool(false)
}







    Esempio di getopt: Introduzione alle opzioni lunghe


<?php
// Script example.php
$shortopts  = "";
$shortopts .= "f:";  // Valore obbligatorio
$shortopts .= "v::"; // Valore facoltativo
$shortopts .= "abc"; // Queste opzioni non accettano valori

$longopts  = array(
    "required:",     // Valore obbligatorio
    "optional::",    // Valore facoltativo
    "option",        // Nessun valore
    "opt",           // Nessun valore
);
$options = getopt($shortopts, $longopts);
var_dump($options);
?>




shell> php example.php -f "valore per f" -v -a --required valore --optional="valore facoltativo" --option


    &example.outputs;


array(6) {
  ["f"]=>
  string(12) "valore per f"
  ["v"]=>
  bool(false)
  ["a"]=>
  bool(false)
  ["required"]=>
  string(6) "valore"
  ["optional"]=>
  string(18) "valore facoltativo"
  ["option"]=>
  bool(false)
}







    Esempio di getopt: Passaggio di più opzioni come una sola


<?php
// Script example.php
$options = getopt("abc");
var_dump($options);
?>




shell> php example.php -aaac


    &example.outputs;


array(2) {
  ["a"]=>
  array(3) {
    [0]=>
    bool(false)
    [1]=>
    bool(false)
    [2]=>
    bool(false)
  }
  ["c"]=>
  bool(false)
}







    Esempio di getopt: Uso di rest_index


<?php
// Script example.php
$rest_index = null;
$opts = getopt('a:b:', [], $rest_index);
$pos_args = array_slice($argv, $rest_index);
var_dump($pos_args);




shell> php example.php -a 1 -b 2 -- prova


    &example.outputs;


array(1) {
  [0]=>
  string(5) "prova"
}
